"use client";

import { useEffect, useRef, useState } from "react";
import AnswerDisplay from "./components/AnswerDisplay";
import ModelSelector from "./components/ModelSelector";
import NavbarMenu from "./components/NavMenu";

interface AIModel { _id: string; modelId: string; displayName: string; }
interface Message { id: string; role: "user" | "assistant"; content: string; modelId?: string; }

function normalizeAnswersToMessages(raw: any): Message[] {
  const answers = Array.isArray(raw?.answers) ? raw.answers : [];
  return answers.map((ans: any) => {
    const id = ans?._id || crypto.randomUUID();
    const content =
      typeof ans?.content === "string" && ans.content.trim()
        ? ans.content
        : "(không có nội dung)";
    let modelId: string | undefined;
    const a = ans?.authorModel;
    if (typeof a === "string") modelId = a;
    else if (a && typeof a === "object") {
      if (typeof a._id === "string") modelId = a._id;
      else if (typeof a.id === "string") modelId = a.id;
      else if (typeof a.modelId === "string") modelId = a.modelId;
    }
    return { id, role: "assistant", content, modelId };
  });
}

export default function Home() {
  // UI
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const mockHistoryData = [
    { name: "Sản phẩm A", href: "/san-pham-a" },
    { name: "Tin tức mới nhất", href: "/tin-tuc" },
  ];

  // App state
  const [question, setQuestion] = useState("");
  const [availableModels, setAvailableModels] = useState<AIModel[]>([]);
  const [selectedModels, setSelectedModels] = useState<AIModel[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Auto-scroll cuối vùng message
  const listEndRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    listEndRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, isLoading]);

  // Load models
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch("/api/models");
        if (!res.ok) throw new Error("Failed to fetch models");
        const data: AIModel[] = await res.json();
        setAvailableModels(data);
      } catch {
        setError("Không thể tải danh sách AI model.");
      }
    })();
  }, []);

  // Submit
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedModels.length === 0) {
      setError("Vui lòng chọn ít nhất một AI model để hỏi.");
      return;
    }
    const q = question.trim();
    if (!q) {
      setError("Vui lòng nhập câu hỏi.");
      return;
    }

    setMessages((prev) => [...prev, { id: crypto.randomUUID(), role: "user", content: q }]);
    setQuestion("");
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch("/api/questions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question: q, selectedModelIds: selectedModels.map((m) => m.modelId) }),
      });
      if (!response.ok) {
        let errorData: any = {};
        try { errorData = await response.json(); } catch {}
        throw new Error(errorData.message || "Yêu cầu thất bại");
      }
      const result = await response.json();
      const assistantMsgs = normalizeAnswersToMessages(result);
      setMessages((prev) => [
        ...prev,
        ...(assistantMsgs.length
          ? assistantMsgs
          : [{ id: crypto.randomUUID(), role: "assistant" as const, content: "Mình chưa nhận được trả lời từ server." }]),
      ]);
    } catch (err: any) {
      setError(err?.message || "Đã xảy ra lỗi khi gửi câu hỏi.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Navbar */}
      <NavbarMenu
        isMenuOpen={isMenuOpen}
        onMenuClick={() => setIsMenuOpen(!isMenuOpen)}
        onClose={() => setIsMenuOpen(false)}
        historyItems={mockHistoryData}
      />

      {/* Nền + chừa chỗ cho navbar */}
      <main className="min-h-screen overflow-x-hidden pt-16 bg-gradient-to-br from-[#8DBCC7] via-[#EBFFD8] to-[#38f9d7]">
        {/* Container cao = (viewport - navbar)
            Flexbox layout với gap nhỏ để các component gần nhau hơn */}
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 h-[calc(100vh-4rem)] flex flex-col gap-6 py-4">

          {/* Model Selector */}
          <div className="flex-shrink-0">
            <div className="w-full max-w-xl ">
              <ModelSelector
                availableModels={availableModels}
                selectedModels={selectedModels}
                setSelectedModels={setSelectedModels}
              />
            </div>
          </div>

          {/* Chat card - chiếm phần còn lại của không gian */}
          <div className="flex-1 min-h-0">
            <div
              className="
                h-full
                rounded-3xl
                bg-white/30 backdrop-blur-xl border border-white/40
                shadow-[0_10px_35px_rgba(0,0,0,0.08)]
                flex flex-col
                overflow-hidden
              "
            >
              {/* Vùng message: dùng min-h-0 để flex item cho phép scroll đúng */}
              <div className="flex-1 min-h-0 overflow-y-auto px-6 py-4">
                <AnswerDisplay
                  messages={messages}
                  isLoading={isLoading}
                  selectedModels={selectedModels}
                  error={error}
                />
                <div ref={listEndRef} />
              </div>

              {/* Ô nhập */}
              <div className="flex-shrink-0 border-t border-white/40 px-6 py-3">
                <form onSubmit={handleSubmit}>
                  <div className="flex items-center gap-2">
                    <input
                      value={question}
                      onChange={(e) => setQuestion(e.target.value)}
                      placeholder="Hỏi bất kỳ điều gì..."
                      className="flex-1 h-12 px-4 rounded-full bg-white/90 text-gray-900 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-[#79A3B1] focus:border-transparent shadow-md"
                    />
                    <button
                      type="submit"
                      disabled={isLoading}
                      className="h-12 px-5 rounded-full bg-gradient-to-r from-[#667eea] to-[#764ba2] text-white font-medium shadow-lg hover:shadow-xl hover:-translate-y-0.5 active:translate-y-0 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Gửi
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>

        </div>
      </main>
    </>
  );
}